  <div class="page-head"><div><h2 class="page-title">Statistiche</h2><div class="page-sub">Settembre 2026 · aggiornate stanotte 02:40</div></div><div class="actions"><div class="seg"><button>Settimana</button><button class="active">Mese</button><button>Anno</button></div><button class="btn" data-toast="Export registrato in audit">Esporta</button></div></div>
