PAGES.administration = () => {
  const tab = state.params.tab || 'invoices';
  const full = state.role === 'org_admin';
  const k = FINANCE.kpi;
  const tabs = [['invoices', 'Fatture'], ['services', 'Prestazioni'], ['practitioners', 'Per medico'], ['costs', 'Costi e margine'], ['exports', 'Esportazioni']];
  const kpis = [[k.issued, 'Fatturato emesso', FINANCE.period], [k.collected, 'Incassato', 'DSO ' + k.dso], [k.open, 'Aperto', k.overdue + ' scaduto']].concat(full ? [[k.margin, 'Margine', k.marginPct]] : [['2', 'Bozze da emettere', 'proposte da VISIT_COMPLETED']]);
  const ask = full ? ['Quale medico è più profittevole?', 'Come va il fatturato?', 'Quanto abbiamo di insoluto?'] : ['Quali fatture sono scadute?', 'Come va il fatturato?'];
  return `
    <div class="page-head"><div><h2 class="page-title">Amministrazione</h2><div class="page-sub">Prestazioni, fatture, incassi, costi. Classe dato separata dal clinico: qui non compare nessuna diagnosi.</div></div><div class="actions"><button class="btn" data-toast="Report mensile generato">Report mensile</button><button class="btn primary" data-toast="Nuova fattura (prototipo)">${ICONS.plus} Fattura</button></div></div>
    <div class="grid grid-4">${kpis.map(([v, l, d]) => `<div class="card tight stat"><span class="value num">${v}</span><span class="label">${l}</span><span class="delta">${d}</span></div>`).join('')}</div>
    <div class="card tight mt-16 row" style="gap:8px;flex-wrap:wrap"><span class="badge ai">${ICONS.ai} AI</span><span class="caption">Chiedi in linguaggio naturale: la risposta arriva con la definizione della metrica e il collegamento a questi stessi dati.</span>${ask.map(a => `<button class="chip" data-ai="${a}">${a}</button>`).join('')}</div>
    <div class="tabs mt-16">${tabs.map(([t, l]) => `<button class="tab ${tab === t ? 'active' : ''}" data-go="#/administration/${t}">${l}</button>`).join('')}</div>
    ${({ invoices: admInvoices, services: admServices, practitioners: admPractitioners, costs: admCosts, exports: admExports }[tab] || admInvoices)(full)}`;
};
function admLocked(what) {
  return `<div class="card">${emptyState('shield', 'Non disponibile con il tuo ruolo', `${what} richiede il permesso view_practitioner_performance / view_financial (amministratore organizzativo). Ogni accesso a questi dati è registrato in audit.`)}</div>`;
}
function admInvoices() {
  const ist = { draft: ['Bozza', ''], issued: ['Emessa', 'accent'], paid: ['Pagata', 'success'], overdue: ['Insoluta', 'danger'] };
  return `<div class="table-wrap"><table><thead><tr><th>Numero</th><th>Paziente</th><th>Data</th><th>Importo</th><th>Stato</th><th></th></tr></thead><tbody>${INVOICES.map(i => `<tr><td class="num"><b>${i.n}</b></td><td>${fullName(P[i.p])}</td><td class="num">${i.date}</td><td class="num">${i.amount}</td><td><span class="badge ${ist[i.status][1]}">${ist[i.status][0]}</span></td><td>${i.status === 'draft' ? `<button class="btn sm primary" data-toast="Fattura ${i.n} emessa - audit">Emetti</button>` : i.status === 'overdue' ? `<button class="btn sm" data-toast="Sollecito preparato (invio manuale)">Sollecito</button>` : `<button class="btn sm ghost">${ICONS.print}</button>`}</td></tr>`).join('')}</tbody></table></div>
    <div class="card mt-16"><div class="card-head"><span class="section-title">Crediti aperti per scadenza</span><span class="caption">metrica open_receivables v2</span></div>${FINANCE.aging.map(([l, v]) => `<div class="row" style="margin-bottom:8px"><span style="width:120px;font-size:13px">${l}</span><div class="meter grow ${l === 'oltre 90 gg' ? 'warn' : ''}"><i style="width:${Math.round(v / 200)}%"></i></div><span class="caption num" style="width:90px;text-align:right">${chf(v)}</span></div>`).join('')}</div>`;
}
