function systemBackups() { return `<div class="grid grid-3"><div class="card"><div class="card-head"><span class="section-title">L1 · Snapshot</span><span class="status"><i class="dot success"></i>ok</span></div><div class="kv"><b>Frequenza</b><span>15 min + WAL</span><b>Ultimo</b><span>11:30</span><b>Dove</b><span>disco esterno cifrato</span></div></div><div class="card"><div class="card-head"><span class="section-title">L2 · Giornaliero</span><span class="status"><i class="dot success"></i>verificato</span></div><div class="kv"><b>Ultimo</b><span>02:10 · 96 GB</span><b>Restore test</b><span>01.09 · OK</span><b>Dove</b><span>NAS studio (restic)</span><b>Prossimo</b><span>02:00</span></div></div><div class="card"><div class="card-head"><span class="section-title">L3 · Off-site</span><span class="status"><i class="dot success"></i>ok</span></div><div class="kv"><b>Ultimo</b><span>dom 06.09</span><b>Supporto</b><span>disco #2 (rotazione)</span><b>Cloud</b><span>disabilitato</span></div></div></div><div class="row mt-16"><button class="btn primary" data-toast="Backup L2 avviato">${ICONS.backup} Backup ora</button><button class="btn" data-toast="Test di restore avviato su istanza di test">Test restore</button><button class="btn" data-modal="restore">Ripristina…</button><span class="caption">RPO 15 min · RTO 4 h su hardware di riserva · un backup è valido solo dopo restore verificato</span></div>`; }
function systemPrivacy() { return `<div class="grid grid-2"><div class="card"><div class="card-head"><span class="section-title">Dove risiedono i dati</span></div><div class="list">${[['Database, documenti, audio', 'Mac mini · /opt/referralflow/storage · FileVault + chiave app'], ['Backup', 'Disco esterno cifrato · NAS studio · disco off-site (cassaforte)'], ['Modelli AI', 'Mac mini + DGX Spark #1 · rete privata'], ['Servizi esterni', 'Nessuno · external_ai.enabled = false']].map(([a, b]) => `<div class="list-item"><i class="dot success"></i><div><div class="name" style="font-size:13px">${a}</div><div class="sub">${b}</div></div></div>`).join('')}</div></div><div class="card"><div class="card-head"><span class="section-title">Ultime 24 h</span></div><div class="grid grid-2" style="gap:10px">${[['41', 'accessi a dati clinici'], ['0', 'export'], ['0', 'tentativi falliti'], ['6', 'dispositivi attivi'], ['1', 'break-glass (0)'], ['0', 'servizi esterni usati']].map(([v, l]) => `<div class="stat"><span class="value num" style="font-size:22px">${v}</span><span class="label" style="font-size:12px">${l}</span></div>`).join('')}</div><div class="row mt-16"><button class="btn" data-toast="Registro dei trattamenti generato">Registro trattamenti</button><button class="btn" data-toast="Policy retention aperte">Retention</button></div></div></div>`; }
