  newPatient: () => openSheet('Nuovo paziente', `<div class="grid grid-2"><div class="field"><label>Nome</label><input class="input" style="width:100%" value="Mario"></div><div class="field"><label>Cognome</label><input class="input" style="width:100%" value="Rossi"></div><div class="field"><label>Data di nascita</label><input class="input" type="date" value="1959-03-12" style="width:100%"></div><div class="field"><label>Telefono</label><input class="input" style="width:100%"></div></div><div class="alert important"><div class="grow"><div class="a-title">Possibile duplicato</div><div class="a-body">Mario Rossi · 12.03.1959 · ID 10231 · +41 79 412 33 21 — corrispondenza su nome, cognome e data di nascita.</div><div class="a-actions"><button class="btn sm primary" data-go="#/patients/p1">Usa esistente</button><button class="btn sm" data-toast="Creato come nuovo (duplicato dichiarato) · audit">Crea comunque</button></div></div></div>`, `<button class="btn" onclick="closeSheet()">Annulla</button>`),
